solution.js:
// Pocket's storage helpers. In this playground, localStorage works but starts
// empty on every run; on a real page it keeps its data between visits.
const STORAGE_KEY = "pocket.expenses.v1";

function saveExpenses(expenses) {
  localStorage.setItem(STORAGE_KEY, JSON.stringify(expenses));
}

function loadExpenses() {
  try {
    const text = localStorage.getItem(STORAGE_KEY);
    const data = text === null ? [] : JSON.parse(text);
    return Array.isArray(data) ? data : [];
  } catch {
    return [];
  }
}

saveExpenses([{ id: "exp-1", label: "Coffee", amount: 450 }]);
console.log(localStorage.getItem(STORAGE_KEY));

