localStorage.clear();
saveExpenses([{ id: 'a', label: 'Tea', amount: 300 }]);
const raw = localStorage.getItem('pocket.expenses.v1');
try { const back = JSON.parse(raw); return Array.isArray(back) && back[0].label === 'Tea' && back[0].amount === 300; } catch { return false; }

localStorage.clear();
const data = [{ id: 'a', label: 'Tea', amount: 300 }, { id: 'b', label: 'Bus', amount: 270 }];
saveExpenses(data);
const back = loadExpenses();
return Array.isArray(back) && back.length === 2 && back[1].label === 'Bus' && back[1].amount === 270 && back !== data;

localStorage.clear();
const out = loadExpenses();
return Array.isArray(out) && out.length === 0;

